-- Fixed shipped 0.10.4 schema, prior to Autopilot simplification.
CREATE TABLE jobs (_id INTEGER PRIMARY KEY AUTOINCREMENT, thread INTEGER NOT NULL, address TEXT NOT NULL, body TEXT NOT NULL, base INTEGER NOT NULL, sub INTEGER NOT NULL, due INTEGER NOT NULL, approved INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', uri TEXT NOT NULL DEFAULT '', parts INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, auto_send INTEGER NOT NULL DEFAULT 0, profile_revision INTEGER NOT NULL DEFAULT 0, config_revision TEXT NOT NULL DEFAULT '', original TEXT NOT NULL DEFAULT '', delivery_status TEXT NOT NULL DEFAULT 'none', delivered_at INTEGER NOT NULL DEFAULT 0, sms_date INTEGER NOT NULL DEFAULT 0, sleep_revision INTEGER NOT NULL DEFAULT 0, auto_delay INTEGER NOT NULL DEFAULT -1, location_revision INTEGER NOT NULL DEFAULT 0, location_expires INTEGER NOT NULL DEFAULT 0, attention_kind TEXT NOT NULL DEFAULT '');
CREATE TABLE relationships(thread INTEGER PRIMARY KEY, body TEXT NOT NULL, revision INTEGER NOT NULL, samples TEXT NOT NULL DEFAULT '', cloud_enabled INTEGER NOT NULL DEFAULT 0, auto_draft INTEGER NOT NULL DEFAULT 0, relationship_kind TEXT NOT NULL DEFAULT '', tone TEXT NOT NULL DEFAULT '', auto_send INTEGER NOT NULL DEFAULT 0, auto_delay INTEGER NOT NULL DEFAULT 300, auto_delay_mode TEXT NOT NULL DEFAULT 'fixed', auto_delay_min INTEGER NOT NULL DEFAULT 300, auto_delay_max INTEGER NOT NULL DEFAULT 1800, engagement TEXT NOT NULL DEFAULT 'natural', share_location INTEGER NOT NULL DEFAULT 0, humor_level INTEGER NOT NULL DEFAULT 0, inside_jokes TEXT NOT NULL DEFAULT '', important_details TEXT NOT NULL DEFAULT '', plan_handling TEXT NOT NULL DEFAULT 'ask_me');
CREATE TABLE drafts(thread INTEGER PRIMARY KEY, base INTEGER NOT NULL, body TEXT NOT NULL, alternatives TEXT NOT NULL, engine TEXT NOT NULL, location_revision INTEGER NOT NULL DEFAULT 0, location_expires INTEGER NOT NULL DEFAULT 0, source_mms INTEGER NOT NULL DEFAULT 0, source_mms_date INTEGER NOT NULL DEFAULT 0, source_text TEXT NOT NULL DEFAULT '', source_address TEXT NOT NULL DEFAULT '');
CREATE TABLE reply_holds(thread INTEGER PRIMARY KEY, base INTEGER NOT NULL, latest_base INTEGER NOT NULL, created INTEGER NOT NULL, delay_attempted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE reply_decisions(thread INTEGER NOT NULL, base INTEGER NOT NULL, reason TEXT NOT NULL, created INTEGER NOT NULL, PRIMARY KEY(thread,base));
CREATE TABLE attention_actions(token TEXT PRIMARY KEY, thread INTEGER NOT NULL, base INTEGER NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, profile_revision INTEGER NOT NULL, config_revision TEXT NOT NULL, fingerprint TEXT NOT NULL, burst INTEGER NOT NULL, state TEXT NOT NULL, created INTEGER NOT NULL, job_id INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', auto_plan INTEGER NOT NULL DEFAULT 0, auto_sleep_revision INTEGER NOT NULL DEFAULT 0, UNIQUE(thread,base,action));
CREATE TABLE manual_takeovers(thread INTEGER PRIMARY KEY,revision INTEGER NOT NULL,sms_id INTEGER NOT NULL,sms_date INTEGER NOT NULL,sms_signature TEXT NOT NULL,sms_receipt INTEGER NOT NULL DEFAULT 0,mms_id INTEGER NOT NULL,mms_date INTEGER NOT NULL,mms_signature TEXT NOT NULL,mms_receipt INTEGER NOT NULL DEFAULT 0,claimed_at INTEGER NOT NULL);
CREATE TABLE manual_sends(request_id TEXT PRIMARY KEY,thread INTEGER NOT NULL,address TEXT NOT NULL,body TEXT NOT NULL,sub INTEGER NOT NULL,job_id INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
